// /portal/energie – Energie & Lastgang (Fachprüfung Kapitalseite): Abnahmestellen mit MaLo/MeLo bzw. Zählpunkt,
// Liefervertrag und Entlastungen; Lastgang-Import mit Analyse, PV-Deckung und Pool-Ersparnis → Angebotsanfrage.
// Rolle „unternehmen“ (Backoffice liest mit ?nutzerId=).

import { Gauge, SunMedium } from "lucide-react";
import Button from "@/components/ui/Button";
import Begriff from "@/components/Portal/Bedienung/Begriff";
import { Hinweis, Karte, SeitenKopf } from "@/components/Portal/ui";
import Abnahmestellen from "@/components/Portal/Fach/Energie/Abnahmestellen";
import Lastgang from "@/components/Portal/Fach/Energie/Lastgang";
import { portalNutzer, laden, istAdmin } from "@/lib/plattform/server/seite";
import { fachBackend } from "@/lib/plattform/backend/fach";

export const metadata = { title: "Energie & Lastgang" };

export default async function EnergieSeite({ searchParams }) {
  const sp = await searchParams;
  const n = await portalNutzer({ rollen: ["unternehmen"] });
  const admin = istAdmin(n);
  const d = await laden(() => fachBackend().energieDaten(n, { nutzerId: admin ? sp?.nutzerId : undefined }));
  const eigen = n.rollen.includes("unternehmen") && !(admin && sp?.nutzerId);
  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Reststrom-Pool & Contracting"
        titel="Energie & Lastgang"
        text="Ihre Abnahmestellen mit Mess- und Marktlokation, Liefervertrag und Entlastungen – und die Analyse Ihres Lastgangs: Spitze, Benutzungsstunden, Grundlast, Wochenprofil, PV-Potenzial und Ersparnis im Reststrom-Pool."
        aktionen={<Button href="/portal/anlagen" size="sm" variant="secondary" icon={SunMedium}>Mein Solarstrom</Button>}
      />
      <Hinweis ton="info" icon={Gauge} titel="Wofür wir diese Angaben brauchen">
        Für ein belastbares Angebot braucht der Pool die <Begriff id="marktlokation">Marktlokation</Begriff>, die Messart (<Begriff id="rlm">RLM</Begriff> oder <Begriff id="slp">SLP</Begriff>) und idealerweise den <Begriff id="lastgang">Lastgang</Begriff> der letzten zwölf Monate. Ihre Daten nutzen wir nur für Analyse und Angebot; die Zeitreihe verlässt das Portal nicht.
      </Hinweis>
      <Karte titel="Abnahmestellen" untertitel="Je Zähler bzw. Standort eine Abnahmestelle – Prüfung der Identifikatoren beim Speichern">
        {eigen ? <Abnahmestellen liste={d.abnahmestellen} /> : <p className="text-[14px] text-ink-600">{d.abnahmestellen.length} Abnahmestellen (nur lesen).</p>}
      </Karte>
      <Karte titel="Lastgang & Analyse" untertitel="CSV mit Viertelstunden- oder Stundenwerten – bis zu drei Jahre">
        <Lastgang lastgaenge={d.lastgaenge} abnahmestellen={d.abnahmestellen} unternehmen={eigen} />
      </Karte>
    </div>
  );
}
// /portal/energie/beschaffung – „Meine Energiebeschaffung“ (Rolle unternehmen): laufender Vertrag, Wechselanalyse,
// Ersparnis gegenüber dem Vorvertrag, Ausschreibungsstatus, Angebotsvergleich zur Freigabe, Beschaffungsvollmacht,
// Dokumente. Abnahmestellen und Lastgang pflegt der Kunde unter /portal/energie (Fachprüfung).

import Link from "next/link";
import { Karte, SeitenKopf } from "@/components/Portal/ui";
import { Wert } from "@/components/Portal/Anlagen/teile";
import { BalkenChart, FARBEN, Legende } from "@/components/Portal/Energie/Diagramme";
import { FreigabeKnoepfe, VertragFormular, VollmachtKarte } from "@/components/Portal/Energie/Formulare";
import { EmpfehlungBadge, FristBadge, Hinweis, PdfLink, StatusBadgeEnergie, Tabelle, ct, datum, datumZeit, eur, fmt, monatText } from "@/components/Portal/Energie/teile";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { energieBackend } from "@/lib/plattform/backend/energie";
import { RECHTSHINWEISE } from "@/lib/plattform/energie/texte";

export const metadata = { title: "Meine Energiebeschaffung" };

export default async function MeineEnergiebeschaffung() {
  const n = await portalNutzer({ rollen: ["unternehmen"] });
  if (!n.rollen.includes("unternehmen")) {
    return (
      <>
        <SeitenKopf eyebrow="Energiebeschaffung" titel="Meine Energiebeschaffung" text="Diese Ansicht ist für Unternehmenskonten. Das Backoffice nutzt den Handelsdesk." />
        <Link href="/portal/admin/energie" className="font-semibold text-ov-700 hover:text-ov-800">Zum Handelsdesk</Link>
      </>
    );
  }
  const d = await laden(() => energieBackend().energieMeine(n));
  const vt = d.vertraege.find((x) => ["aktiv", "gekuendigt"].includes(x.status) && x.quelle !== "zuschlag") || null;
  const neu = d.vertraege.filter((x) => x.quelle === "zuschlag");
  const w = d.analyse;
  const freigabe = d.ausschreibungen.filter((a) => a.status === "freigabe" && a.vorschlag);
  const ersparnis = d.ersparnis.reduce((s, x) => s + (x.eurJahr || 0), 0);
  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Reststrom-Pool"
        titel="Meine Energiebeschaffung"
        text="ÖkoInvest holt für Ihren Reststrom Angebote mehrerer Energieversorger ein – einzeln oder gebündelt im Pool – und überwacht laufend, ob sich ein Wechsel lohnt. Ohne Ihre Freigabe wird kein Vertrag geschlossen."
        aktionen={<Link href="/portal/energie" className="inline-flex h-10 items-center rounded-full bg-white px-4 text-[14px] font-semibold text-ink-900 ring-1 ring-inset ring-ink-200 hover:bg-ink-50">Abnahmestellen & Lastgang</Link>}
      />
      <section aria-label="Überblick" className="grid grid-cols-2 gap-3 md:grid-cols-4">
        <Wert ton="dunkel" label="Aktueller Vertrag" wert={vt ? ct(vt.energiepreisCt) : "–"} hinweis={vt ? `${vt.lieferantName} · bis ${datum(vt.vertragEnde)}` : "noch nicht erfasst"} />
        <Wert label="Kündigung bis" wert={vt?.kuendigungsStichtag ? datum(vt.kuendigungsStichtag) : "–"} hinweis={vt?.tageBisStichtag !== null && vt?.tageBisStichtag !== undefined ? `${vt.tageBisStichtag} Tage` : ""} />
        <Wert label="Markteinschätzung" wert={w ? w.label : "–"} hinweis={w?.marktCt ? `Markt ${ct(w.marktCt)}` : ""} />
        <Wert label="Ersparnis ggü. Vorvertrag" wert={d.ersparnis.length ? eur(ersparnis) : "–"} hinweis={d.ersparnis.some((x) => x.erwartet) ? "pro Jahr, erwartet (Tranchen)" : "pro Jahr"} />
      </section>

      {freigabe.map((a) => (
        <Karte key={a.id} id={`freigabe-${a.id}`} titel="Angebotsvergleich zur Freigabe" untertitel={`${a.titel} · Lieferbeginn ${monatText(a.lieferbeginn)}${a.pool ? " · Pool" : ""}`} aktion={<PdfLink href={`/api/portal/energie/dokument?art=vergleich&id=${a.id}`}>PDF</PdfLink>}>
          <div className="grid gap-6 xl:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
            <div className="grid gap-4">
              <div className="rounded-2xl bg-ov-50 p-4 ring-1 ring-ov-200">
                <p className="text-[12.5px] font-semibold uppercase tracking-wide text-ov-800">Vorschlag von ÖkoInvest</p>
                <p className="mt-1 font-display text-[20px] font-extrabold text-ink-900">{a.vorschlag.lieferant}</p>
                <p className="text-[14px] text-ink-700">{a.vorschlag.produkt} · {ct(a.vorschlag.ctKwh, 3)} · rund {eur(a.vorschlag.eurJahr)} pro Jahr (Energie)</p>
                {a.vorschlag.ersparnisEurJahr !== null && <p className="mt-1 text-[14px] font-semibold text-ov-900">Gegenüber Ihrem bisherigen Energiepreis ({ct(a.vorschlag.altCt, 3)}): {eur(a.vorschlag.ersparnisEurJahr)} pro Jahr</p>}
                {a.vorschlag.begruendung && <p className="mt-2 text-[13.5px] text-ink-700">{a.vorschlag.begruendung}</p>}
                <p className="mt-2 text-[12.5px] text-ink-500">Angebot bindend bis {datumZeit(a.vorschlag.bindefristBis)} · Zahlungsziel {a.vorschlag.zahlungszielTage} Tage · Sicherheit: {a.vorschlag.sicherheit}</p>
              </div>
              <Tabelle kopf={["Rang", "Versorger", "Produkt", "ct/kWh", "€/Jahr"]} rechts={[3, 4]} zeilen={a.vergleich.zeilen.map((z) => [z.rang, z.lieferant, z.produkt, fmt(z.ctKwh, 3), eur(z.eurJahr)])} />
              <p className="text-[12.5px] leading-snug text-ink-500">Normiert auf Ihr Verbrauchsprofil, ohne Netzentgelte, Umlagen, Abgaben und Steuern (die ändern sich durch den Wechsel nicht).</p>
            </div>
            <div className="grid gap-4">
              <p className="text-[13.5px] font-semibold text-ink-800">Was passiert bei Marktbewegungen?</p>
              <BalkenChart
                kategorien={a.vergleich.szenarien.map((s) => `${s > 0 ? "+" : ""}${s} %`)}
                reihen={a.vergleich.zeilen.slice(0, 3).map((z, i) => ({ name: `${z.lieferant} – ${z.produkt}`, farbe: [FARBEN.navy, FARBEN.gruen, FARBEN.sonne][i], werte: a.vergleich.szenarien.map((s) => z.sensitivitaet[s]) }))}
                yEinheit="€/Jahr"
                format={(x) => fmt(x, 0)}
                hoehe={220}
                beschreibung="Kosten der besten Angebote bei Marktbewegungen" breite={520}
              />
              <Legende eintraege={a.vergleich.zeilen.slice(0, 3).map((z, i) => ({ name: `${z.lieferant} – ${z.produkt}`.slice(0, 60), farbe: [FARBEN.navy, FARBEN.gruen, FARBEN.sonne][i] }))} />
              {a.eigeneFreigabe ? <Hinweis>Ihre Entscheidung: {a.eigeneFreigabe.entscheidung} am {datumZeit(a.eigeneFreigabe.am)}.</Hinweis> : <FreigabeKnoepfe ausschreibungId={a.id} />}
            </div>
          </div>
        </Karte>
      ))}

      <div className="grid gap-6 xl:grid-cols-2">
        <Karte titel="Wechselanalyse" untertitel="Ihr Vertrag im Vergleich zur aktuellen Terminkurve" aktion={w ? <EmpfehlungBadge empfehlung={w.empfehlung} label={w.label} /> : null}>
          {w ? (
            <ul className="grid gap-1.5 text-[14px] leading-relaxed text-ink-700">
              {w.begruendung.map((t, i) => <li key={i} className="flex gap-2"><span aria-hidden="true" className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-ov-500" />{t}</li>)}
            </ul>
          ) : (
            <p className="text-[14px] text-ink-600">Erfassen Sie Ihren laufenden Stromvertrag – dann überwachen wir Kündigungsfrist und Marktpreis für Sie.</p>
          )}
        </Karte>
        <Karte titel="Beschaffungsvollmacht" untertitel="Damit ÖkoInvest Angebote einholen und – nach Ihrer Freigabe – den Wechsel einleiten darf">
          <VollmachtKarte vollmacht={d.vollmacht} text={d.vollmachtText} version={d.vollmachtVersion} />
        </Karte>
      </div>

      <Karte titel="Ausschreibungen" untertitel="Status Ihrer Angebotsanfragen">
        <Tabelle
          kopf={["Ausschreibung", "Lieferbeginn", "Runde", "Angebote", "Status", ""]}
          zeilen={d.ausschreibungen.map((a) => [a.titel, monatText(a.lieferbeginn), a.runden.length ? `${a.runden.length}${a.runden[a.runden.length - 1].offen ? ` · Frist ${datumZeit(a.runden[a.runden.length - 1].frist)}` : ""}` : "–", `${a.angeboteAnzahl} Versorger`, <StatusBadgeEnergie key="s" status={a.status} />, a.status === "zuschlag" ? <PdfLink key="p" href={`/api/portal/energie/dokument?art=vergleich&id=${a.id}`}>Vergleich</PdfLink> : ""])}
          leer="Noch keine Ausschreibung – mit erteilter Vollmacht startet ÖkoInvest sie rechtzeitig vor Ihrem Kündigungsstichtag."
        />
      </Karte>

      <Karte titel="Meine Stromverträge" untertitel="Laufend, gekündigt und neu über ÖkoInvest">
        <Tabelle
          kopf={["Lieferant", "Struktur", "Preis", "Laufzeit", "Kündigung", "Status"]}
          zeilen={d.vertraege.map((x) => [x.lieferantName || x.lieferant, x.strukturLabel + (x.pool ? " · Pool" : ""), x.preisCt !== null && x.preisCt !== undefined ? `${fmt(x.preisCt, 3)} ct${x.preisArt === "gesamt" ? " (gesamt)" : ""}` : x.aufschlagCt !== undefined && x.aufschlagCt !== null ? `Tranchen/Spot + ${fmt(x.aufschlagCt, 3)} ct` : "–", `${datum(x.beginn)} – ${datum(x.vertragEnde)}`, <FristBadge key="f" tage={x.tageBisStichtag} />, x.status])}
          leer="Noch kein Vertrag erfasst."
        />
        {neu.length > 0 && <p className="mt-3 text-[13px] text-ink-600">Neue Verträge aus einem Zuschlag: Den Lieferantenwechsel und die Kündigung des bisherigen Vertrags leitet ÖkoInvest ein.</p>}
        <div className="mt-5 border-t border-ink-100 pt-5">
          <VertragFormular url="/api/portal/energie" vertrag={vt && vt.quelle !== "zuschlag" ? vt : null} titel={vt ? "Laufenden Vertrag bearbeiten" : "Laufenden Vertrag erfassen"} />
        </div>
      </Karte>
      <Hinweis>{RECHTSHINWEISE.datenschutz} {RECHTSHINWEISE.wechselDe} {RECHTSHINWEISE.wechselAt}</Hinweis>
      {!d.fach.abnahmestellen && <Hinweis ton="warn">Für belastbare Angebote bitte Abnahmestellen (Marktlokation bzw. Zählpunkt) und – bei RLM – den Lastgang unter „Abnahmestellen & Lastgang“ hinterlegen.</Hinweis>}
    </div>
  );
}
// /portal/ausschreibungen – Versorger-Portal (Rolle „lieferant“): nur Ausschreibungen, zu denen der Versorger eingeladen ist.

import Link from "next/link";
import { redirect } from "next/navigation";
import { FileText } from "lucide-react";
import { Karte, Leer, SeitenKopf } from "@/components/Portal/ui";
import { Hinweis, StatusBadgeEnergie, Tabelle, datumZeit, fmt, monatText } from "@/components/Portal/Energie/teile";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { energieBackend } from "@/lib/plattform/backend/energie";
import { LIEFERANT_BEDINGUNGEN } from "@/lib/plattform/energie/texte";

export const metadata = { title: "Angebotsanfragen Strom" };

const ERGEBNIS = { zuschlag: "Zuschlag", absage: "Absage", ohne_angebot: "ohne Angebot", abgebrochen: "abgebrochen" };

export default async function LieferantAusschreibungen() {
  const n = await portalNutzer({ rollen: ["lieferant"] });
  if (n.rollen.includes("admin")) redirect("/portal/admin/energie/ausschreibungen");
  const liste = await laden(() => energieBackend().energieAusschreibungen(n, {}));
  return (
    <>
      <SeitenKopf eyebrow="Versorger-Portal" titel="Angebotsanfragen" text="Ausschreibungen von ÖkoInvest für Gewerbe- und Industriekunden (einzeln oder im Pool), zu denen Sie eingeladen sind – mit anonymisiertem Lastprofil, Preisblatt, Fristen und Fragen." />
      {liste.length ? (
        <Karte titel="Ihre Einladungen" innen="p-0 md:p-2">
          <Tabelle
            kopf={["Los", "Lieferbeginn", "Menge", "Runde / Frist", "Ihre Angebote", "Status"]}
            rechts={[2, 4]}
            zeilen={liste.map((a) => [
              <div key={a.id}>
                <Link href={`/portal/ausschreibungen/${a.id}`} className="font-semibold text-ov-700 hover:text-ov-800">{a.los}</Link>
                <p className="text-[12px] text-ink-500">{a.titel}</p>
              </div>,
              monatText(a.lieferbeginn),
              a.jahresMengeMwh ? `${fmt(a.jahresMengeMwh)} MWh` : "–",
              a.runde ? `R${a.runde.nr} · ${datumZeit(a.runde.frist)}${a.darfBieten ? " · offen" : ""}` : "–",
              a.eigeneAngebote,
              a.ergebnis ? ERGEBNIS[a.ergebnis] || a.ergebnis : <StatusBadgeEnergie key="s" status={a.status} />,
            ])}
          />
        </Karte>
      ) : (
        <Leer icon={FileText} titel="Noch keine Angebotsanfragen" text="Sobald ÖkoInvest Sie zu einer Ausschreibung einlädt, erscheint sie hier. Sie erhalten zusätzlich eine E-Mail." />
      )}
      <div className="mt-6">
        <Hinweis>
          <span className="whitespace-pre-line">{LIEFERANT_BEDINGUNGEN}</span>
        </Hinweis>
      </div>
    </>
  );
}
// /portal/ausschreibungen/[id] – Angebotsanfrage aus Sicht des Versorgers: anonymisiertes Los, Produktvarianten, Preisblatt,
// eigene Angebote, Hinweis der Folgerunde (ohne Namen), Fragen & Antworten. Nicht eingeladen → 404.

import { redirect } from "next/navigation";
import { Angaben, Karte, SeitenKopf } from "@/components/Portal/ui";
import { Wert } from "@/components/Portal/Anlagen/teile";
import { BalkenChart, FARBEN, Heatmap } from "@/components/Portal/Energie/Diagramme";
import { AktionKnopf, FrageFormular, Preisblatt } from "@/components/Portal/Energie/Formulare";
import { Hinweis, PdfLink, StatusBadgeEnergie, Tabelle, datumZeit, fmt, monatText } from "@/components/Portal/Energie/teile";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { energieBackend } from "@/lib/plattform/backend/energie";
import { SICHERHEITEN } from "@/lib/plattform/energie/ausschreibung";

export const metadata = { title: "Angebotsanfrage Strom" };

const MONATE = ["Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"];
const ebeneLabel = { ns: "Niederspannung", ms_ns: "Umspannung MS/NS", ms: "Mittelspannung", hs_ms: "Umspannung HS/MS", hs: "Hochspannung" };

export default async function LieferantAusschreibung({ params }) {
  const n = await portalNutzer({ rollen: ["lieferant", "unternehmen"] });
  const { id } = await params;
  if (n.rollen.includes("admin")) redirect(`/portal/admin/energie/ausschreibungen/${id}`);
  const r = await laden(() => energieBackend().energieAusschreibung(n, id));
  if (r.rolle === "kunde") redirect("/portal/energie/beschaffung");
  const a = r.ausschreibung;
  const p = a.profil;
  const letztes = a.eigeneAngebote.find((g) => g.runde === a.runde?.nr && g.status === "abgegeben") || null;
  return (
    <>
      <SeitenKopf
        eyebrow={`Angebotsanfrage · ${a.los}`}
        titel={a.titel}
        text="Anonymisiertes Los: Kundennamen, Anschriften und Lokations-IDs erhalten Sie erst nach Zuschlag und Freigabe durch den Kunden."
        aktionen={
          <>
            <StatusBadgeEnergie status={a.status} />
            {a.ergebnis === "zuschlag" && <PdfLink href={`/api/portal/energie/dokument?art=zuschlag&id=${a.id}`}>Zuschlagsschreiben</PdfLink>}
          </>
        }
      />
      {a.ergebnis && <div className="mb-6"><Hinweis ton={a.ergebnis === "zuschlag" ? "info" : "warn"}>{a.ergebnis === "zuschlag" ? "Ihr Angebot hat den Zuschlag erhalten. ÖkoInvest übermittelt die Kundendaten für den Lieferantenwechsel gesondert." : a.ergebnis === "absage" ? "Der Zuschlag ging an einen anderen Versorger. Vielen Dank für Ihr Angebot." : a.ergebnis === "abgebrochen" ? "Die Angebotsanfrage wurde ohne Zuschlag beendet." : "Die Ausschreibung ist abgeschlossen."}</Hinweis></div>}
      <section aria-label="Eckdaten" className="mb-6 grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6">
        <Wert ton="dunkel" label="Angebotsfrist" wert={a.runde ? datumZeit(a.runde.frist) : "–"} hinweis={a.runde ? `Runde ${a.runde.nr}${a.runde.offen ? " · offen" : " · geschlossen"}` : ""} />
        <Wert label="Lieferbeginn" wert={monatText(a.lieferbeginn)} hinweis={a.zone === "AT" ? "Gebotszone AT" : "Gebotszone DE-LU"} />
        <Wert label="Jahresmenge" wert={`${fmt(p.jahresMengeMwh)} MWh`} hinweis={`${p.anzahlKunden} · ${p.abnahmestellen} Abnahmestellen`} />
        <Wert label="Spitze" wert={`${fmt(p.spitzeKw)} kW`} hinweis={`${fmt(p.benutzungsstunden)} Benutzungsstunden`} />
        <Wert label="Peak-Anteil" wert={`${p.peakAnteilProzent} %`} hinweis="Mo–Fr 8–20 Uhr" />
        <Wert label="Spannungsebene" wert={Object.keys(p.spannungsebenen).map((k) => ebeneLabel[k] || k).join(", ") || "–"} hinweis={Object.keys(p.messarten).map((k) => k.toUpperCase()).join(", ")} />
      </section>
      {a.hinweis && <div className="mb-6"><Hinweis>{a.hinweis.text}</Hinweis></div>}
      <div className="mb-6 grid gap-6 xl:grid-cols-2">
        <Karte titel="Lastprofil (normiert)" untertitel="Faktor zur mittleren Last je Wochentag und Stunde – keine Rohdaten">
          <Heatmap matrix={p.wochenprofil} einheit="× Mittel" beschreibung="Normiertes Wochenprofil des Loses" breite={520} />
        </Karte>
        <Karte titel="Monatsverteilung" untertitel="Anteil an der Jahresmenge in %">
          <BalkenChart kategorien={MONATE} reihen={[{ name: "Anteil", farbe: FARBEN.navy, werte: p.monatsanteileProzent }]} yEinheit="%" hoehe={220} beschreibung="Monatsanteile an der Jahresmenge" breite={520} />
        </Karte>
      </div>
      <Karte titel="Produktvarianten" className="mb-6">
        <ul className="grid gap-2 text-[14px] text-ink-700">
          {a.produkte.map((x) => <li key={x.id}><strong className="text-ink-900">{x.id}: {x.label}</strong> – {x.text}</li>)}
        </ul>
      </Karte>
      {a.darfBieten ? (
        <Karte titel={letztes ? `Ihr Angebot ersetzen (Version ${letztes.version})` : "Preisblatt"} untertitel={`Verdeckt bis ${datumZeit(a.runde.frist)} – danach gesperrt`} className="mb-6">
          <Preisblatt a={a} letztes={letztes} />
          {letztes && <div className="mt-4"><AktionKnopf url={`/api/portal/ausschreibungen/${a.id}/angebot`} body={{ aktion: "zurueckziehen", angebotId: letztes.id }} label="Angebot zurückziehen" bestaetigen="Angebot wirklich zurückziehen?" variant="ghost" /></div>}
        </Karte>
      ) : (
        a.status === "laufend" && a.runde && !a.runde.zugelassen && <div className="mb-6"><Hinweis ton="warn">Sie sind für die aktuelle Runde nicht zugelassen.</Hinweis></div>
      )}
      <div className="grid gap-6 xl:grid-cols-2">
        <Karte titel="Ihre Angebote">
          <Tabelle
            kopf={["Runde", "Version", "abgegeben", "Positionen", "Bindefrist", "Status"]}
            zeilen={a.eigeneAngebote.map((g) => [g.runde, g.version, datumZeit(g.am), g.positionen.map((x) => `${x.produktId}: ${x.arbeitspreisCt !== null && x.arbeitspreisCt !== undefined ? `${fmt(x.arbeitspreisCt, 3)} ct` : `+${fmt(x.aufschlagCt, 3)} ct`}`).join(" · "), datumZeit(g.bindefristBis), g.status])}
            leer="Noch kein Angebot abgegeben."
          />
          {a.eigeneAngebote[0] && <div className="mt-3"><Angaben items={[{ label: "Zahlungsziel", wert: `${a.eigeneAngebote[0].zahlungszielTage} Tage` }, { label: "Sicherheit", wert: SICHERHEITEN[a.eigeneAngebote[0].sicherheit] || a.eigeneAngebote[0].sicherheit }]} /></div>}
        </Karte>
        <Karte titel="Fragen & Antworten" untertitel="Antworten erhalten alle eingeladenen Versorger – ohne Absender">
          {a.fragen.length > 0 && (
            <ul className="mb-4 grid gap-3">
              {a.fragen.map((f) => (
                <li key={f.id} className="rounded-2xl bg-sand-50 p-4 ring-1 ring-sand-200">
                  <p className="text-[12.5px] text-ink-500">{f.eigene ? "Ihre Frage" : "Frage eines Bieters"} · {datumZeit(f.am)}</p>
                  <p className="mt-1 text-[14px] text-ink-900">{f.text}</p>
                  <p className="mt-2 text-[14px] text-ov-900">{f.antwort ? <><strong>Antwort:</strong> {f.antwort}</> : "Noch nicht beantwortet."}</p>
                </li>
              ))}
            </ul>
          )}
          {a.status === "laufend" && a.runde?.offen ? <FrageFormular id={a.id} /> : <p className="text-[14px] text-ink-500">Fragen sind nur während der Angebotsphase möglich.</p>}
        </Karte>
      </div>
      <div className="mt-6"><Hinweis>Länder: {Object.keys(p.laender).join(", ") || "–"}. Mengen und Spitze sind gerundet. Preise bitte netto ohne Netzentgelte, Umlagen, Abgaben und Steuern angeben; Normierung durch ÖkoInvest auf das Profil des Loses.</Hinweis></div>
    </>
  );
}

