                    ["Arbeitspreis", eur0(a.kosten?.monat?.arbeitEur), eur0(a.kosten?.jahr?.arbeitEur)],
                    ["Grundgebühr", eur0(a.kosten?.monat?.grundEur), eur0(a.kosten?.jahr?.grundEur)],
