                    ["Gleiche Menge aus dem Netz", eur0(a.kosten?.monat?.netzEur), eur0(a.kosten?.jahr?.netzEur)],
                  ].map(([l, m, j, fett]) => (
                    <tr key={l}>
                      <td className={`px-5 py-2.5 md:px-6 ${fett ? "font-semibold text-ink-900" : "text-ink-700"}`}>{l}</td>
