export function Feld({ id, label, hinweis, fehler, pflicht, children, className }) {
  return (
    <div className={cn("min-w-0", className)}>
      {label && (
        <label htmlFor={id} className={labelKlasse}>
          {label}
          {pflicht && <span aria-hidden="true"> *</span>}
